// ─── HEALTH METRICS CALCULATOR ────────────────────────────────────────────
//
// Calculates per-inbox metrics for the past 7 days:
// - Sends, Bounces, Bounce Rate
// - Replies, Reply Rate
// - Health status: GREEN / YELLOW / RED
// - Auto-pause recommendation

const sentLogItems = $('Read Sent Log').all();
const leadsItems = $('Read Leads').all();

const now = new Date();
const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

const inboxes = ['inbox1', 'inbox2', 'inbox3', 'inbox4', 'inbox5'];

// ── Per-inbox metrics ────────────────────────────────────────────────────
const metrics = {};
for (const inbox of inboxes) {
  metrics[inbox] = { sends: 0, bounces: 0, failed: 0 };
}

for (const logItem of sentLogItems) {
  const log = logItem.json;
  const logDate = new Date(log['Timestamp']);
  if (logDate < sevenDaysAgo) continue;

  const inbox = log['Inbox Used'];
  if (!inbox || !metrics[inbox]) continue;

  if (log['Status'] === 'sent') metrics[inbox].sends++;
  if (log['Status'] === 'bounced') metrics[inbox].bounces++;
  if (log['Status'] === 'failed') metrics[inbox].failed++;
}

// ── Reply rates ──────────────────────────────────────────────────────────
const allTimeReplies = leadsItems.filter(i => i.json['Reply Received'] === 'yes').length;
const allTimeSends = sentLogItems.filter(i => i.json['Status'] === 'sent').length;
const globalReplyRate = allTimeSends > 0 ? (allTimeReplies / allTimeSends * 100).toFixed(2) : 0;

// ── Health status per inbox ──────────────────────────────────────────────
const inboxStatuses = {};
for (const inbox of inboxes) {
  const m = metrics[inbox];
  const bounceRate = m.sends > 0 ? (m.bounces / m.sends * 100) : 0;
  m.bounceRate = bounceRate.toFixed(2);

  let status = 'GREEN';
  let shouldPause = false;

  if (bounceRate > 4) {
    status = 'RED';
    shouldPause = true;
  } else if (bounceRate > 2) {
    status = 'YELLOW';
  }

  // If inbox has no sends this week, mark as INACTIVE
  if (m.sends === 0) {
    status = 'INACTIVE';
  }

  inboxStatuses[inbox] = {
    ...m,
    status,
    shouldPause
  };
}

// ── Build summary text ───────────────────────────────────────────────────
let summaryLines = [
  `=== WEEKLY OUTREACH HEALTH REPORT ===`,
  `Week ending: ${now.toDateString()}`,
  ``,
  `GLOBAL METRICS:`,
  `  Total sends (7-day): ${Object.values(metrics).reduce((s, m) => s + m.sends, 0)}`,
  `  Reply rate (all-time): ${globalReplyRate}%`,
  ``,
  `PER-INBOX STATUS:`
];

for (const inbox of inboxes) {
  const s = inboxStatuses[inbox];
  if (s.status === 'INACTIVE') continue;
  summaryLines.push(`  ${inbox.toUpperCase()}: ${s.status} | Sends: ${s.sends} | Bounces: ${s.bounces} | Bounce Rate: ${s.bounceRate}%${s.shouldPause ? ' ← AUTO-PAUSE TRIGGERED' : ''}`);
}

const pausedInboxes = inboxes.filter(i => inboxStatuses[i].shouldPause);
if (pausedInboxes.length > 0) {
  summaryLines.push(``);
  summaryLines.push(`ACTION REQUIRED: Pause ${pausedInboxes.join(', ')} — bounce rate too high.`);
  summaryLines.push(`Set status of leads assigned to these inboxes from 'ready' to 'paused' in Google Sheets.`);
}

const summaryText = summaryLines.join('\n');

return [{
  json: {
    summaryText,
    pausedInboxes,
    inboxStatuses,
    globalReplyRate,
    weekEndDate: now.toDateString(),
    hasRedInbox: pausedInboxes.length > 0
  }
}];

// Mark all 'ready' leads on paused inboxes as 'paused'
const pausedInboxes = $input.item.json.pausedInboxes;

if (!pausedInboxes || pausedInboxes.length === 0) {
  return [];
}

// This node signals n8n — the actual batch update would
// require reading leads and updating each row.
// For simplicity: return a flag and handle in Sheets manually,
// OR chain to a Sheets Update node.
return pausedInboxes.map(inbox => ({
  json: {
    _action: 'pause-inbox',
    inbox,
    message: `Inbox ${inbox} auto-paused due to high bounce rate. Update leads manually in Sheets.`
  }
}));

// Flatten metrics for Sheets row
const data = $input.item.json;
const stats = data.inboxStatuses;

return [{
  json: {
    Week: data.weekEndDate,
    'Global Reply Rate': data.globalReplyRate + '%',
    'Inbox 1 Status': stats.inbox1?.status || 'N/A',
    'Inbox 1 Bounce %': stats.inbox1?.bounceRate || '0',
    'Inbox 2 Status': stats.inbox2?.status || 'N/A',
    'Inbox 2 Bounce %': stats.inbox2?.bounceRate || '0',
    'Inbox 3 Status': stats.inbox3?.status || 'N/A',
    'Inbox 3 Bounce %': stats.inbox3?.bounceRate || '0',
    'Inbox 4 Status': stats.inbox4?.status || 'N/A',
    'Inbox 4 Bounce %': stats.inbox4?.bounceRate || '0',
    'Inbox 5 Status': stats.inbox5?.status || 'N/A',
    'Inbox 5 Bounce %': stats.inbox5?.bounceRate || '0',
    'Red Inboxes': data.pausedInboxes.join(', ') || 'none'
  }
}];
